from pathlib import Path
import csv, datetime as dt, hashlib, io, json

R = Path(__file__).resolve().parents[1]
def bind(p):
    q = R / p
    return dict(path=p, sha256=hashlib.sha256(q.read_bytes()).hexdigest(), bytes=q.stat().st_size)

out = R / 'records/S6_SERIES_PUBLISH_II_provenance_primary_reading_02.json'
assert not out.exists()
pages = [60] + list(range(84, 96))
record = dict(
    created_utc=dt.datetime.now(dt.timezone.utc).isoformat(),
    checker='GPT-6 Astra (OpenAI), ChatGPT Pro mode, root, second continuation; reasoning effort not separately exposed',
    source=bind('S6_SERIES_PUBLISH_II.tex'),
    status='Primary reading and exact credit comparisons; source/deposit revision and final provenance closure remain open',
    primary=dict(
        key='AC2026 / AC26 / AC26Root',
        url='https://alpo.ge/s6.pdf',
        version='Attached original 108-page manuscript; exact bytes bound below. The same public address was reopened online; no byte-identity claim for the online response is made.',
        file=bind('../S6_GRIND_6_literature/original/AC26_original_manuscript.pdf'),
        pages_actually_viewed=pages,
        pdf_pages_one_based=pages,
        images=[bind('../primary_continuation2_root_provenance/AC26-'+str(p).zfill(3)+'.png') for p in pages],
        loci_read=[
            'Theorem 7.22, its complete proof, and Remarks 7.23-7.24 on p.60.',
            'Section 10 introduction and hypotheses (X1)-(X4), pp.84-85.',
            'Section 10.1, full quoted claims and reduction passage, pp.85-86.',
            'Definition 10.1; Lemma 10.2 with both local gluing formulas; Lemma 10.3 and its whole proof; Remark 10.4, pp.86-88.',
            'Theorem 10.5 and all five proof steps; Corollary 10.6 and its proof, pp.88-89.',
            'Section 10.4 complete, pp.89-90.',
            'Section 10.5 complete, including Lemma 10.7, the rational component formula, the precise uses in CDP, and Proposition 10.8 with its complete proof, pp.90-94.',
            'Section 10.6 complete, pp.94-95. The start of Appendix A and displayed matrices visible on p.95 were also read; no reading of the full appendix is claimed.'
        ]),
    exact_comparisons=[
        dict(main='series:II:A', finding='AC26 Lemma 10.3 already constructs the conductor-supported obstruction on a reduced normal-crossing fibre with trivial normalization pullback; Theorem 10.5 proves the degree-two nonvanishing for the standard family, and Section 10.4 locates the CDP p.692 implication. These results require explicit prior credit in the receiving first-page status. The receiving A.1.1 records the general torsion-preimage exact sequence, B1 gives the nodal cubic example, and C4f extends the criterion through its stated full-fibre and normalization maps. The earlier root reading of these complete receiving proofs is bound in record 01.'),
        dict(main='series:II:A', maps='For AC26 E=Omega_X|S tensor A, the conductor pushout sends (eta*(dg) tensor e,0) to a unique global s. Its cotangent image vanishes on the smooth locus, hence lies in T tensor A. In the receiving filtration K is the inverse image of T in V. Thus this same section is in H0(K tensor A), and the exact connecting map sends its image in H0(T tensor A) to zero. The zero/nonzero section comparisons are through the stated inclusions K->V and the conductor descent map, not an identification of the two theorem domains.'),
        dict(main='series:II:B', finding='AC26 p.91 gives exactly r=2g+s-1+t_prime-b1(Y), with t_prime the rational monodromy-coinvariant rank and s nonzero. Main B already credits this locus. Its integral freeness and the general-fibre classification require their separate body comparisons; they are not attributed to that rational calculation.'),
        dict(main='series:II:B', maps='Lemma 10.7 uses G=K semidirect Q and K_prime generated by [K,K] and k^{-1}qkq^{-1}. The quotient map (k,q)->([k],[q]) identifies G_ab with (K_ab)_Q plus Q_ab. Pair duality then identifies H5(Y,A;Q) with H1(U;Q), H5(Y;Q) with H1(Y;Q), and H4(A;Q) with the component span; H4(Y;Q)=0 gives the printed rank formula.'),
        dict(main='series:II:C', finding='Theorem 7.22 p.60 establishes e(X)=e(W)=2 for the original family and its stated homology calculation. The receiving credit to this exact locus is supported. The all-degeneration sign and equality assertions require their own body proofs; the source gives the standard-family value.'),
        dict(main='series:II:E', finding='Theorem 10.5 and Corollary 10.6 already give the standard-family degree-two obstruction and Euler value chi(T_X tensor M)=1. The receiving all-twist dimensions, resonance lengths, and normalization-map ranks must be credited as refinements of that obstruction and compared separately with DGKX version one.'),
        dict(main='uniform nontorsion', finding='AC26 Proposition 10.8 proves one line non-torsion on every full fibre and both reduced multiple fibres. Its proof normalizes L12=f*O(1), identifies the monodromy-invariant cohomology line, and derives the exact period equation c tau+d mu-b=0. Linear independence of 1,tau,mu makes the exceptional rank-two period loci countable; the remaining rank-one loci contribute parameters in R. This prior result needs exact credit wherever this family-wide conclusion is used.')
    ],
    online_queries=[
        dict(engine='system1', main='series:II:D', query='"torus" "Euler characteristic" "even" "degeneration" threefold'),
        dict(engine='system1', main='series:II:B', query='"torus" "coinvariants" "component" "Betti" threefold'),
        dict(engine='system1', main='series:II:E', query='"2610.00250" tangent cohomology')
    ],
    online_result_scope='The bounded searches returned related degeneration work and DGKX secondary listings. The secondary listings supply discovery only; official arXiv version follow-up and attached-primary reading remain required. A Paper V search snippet appeared automatically and was not opened or used for any check. No absence or novelty theorem follows from the returned snippets.',
    online_primary_opening=dict(url='https://alpo.ge/s6.pdf', ref='turn908652677view0', pages=108, scope='Public manuscript address reopened; its title and opening source description match the attached manuscript. Actual visual reading credit belongs to the listed local images.'),
    new_check_events=0,
    final_provenance_claims_closed=0,
    final_publication_page_reading_credit=0
)
out.write_text(json.dumps(record, indent=2)+'\n')
evidence=bind(str(out.relative_to(R)))

p=R/'S6_SERIES_PUBLISH_inventory.csv'
before=p.read_bytes()
reader=csv.DictReader(io.StringIO(before.decode(), newline=''))
fields=reader.fieldnames; rows=list(reader)
oldrows=[dict(r) for r in rows]
changes=[]
for q in record['online_queries']:
    matches=[r for r in rows if r['paper']=='II' and r['label']==q['main']]
    assert len(matches)==1
    row=matches[0]; old=row['literature_searches']
    entries=json.loads(old) if old else []
    entries.append(dict(date_utc=record['created_utc'], engine=q['engine'], query=q['query'], evidence=evidence, scope=record['online_result_scope']))
    row['literature_searches']=json.dumps(entries, ensure_ascii=False)
    changes.append(dict(paper='II',label=row['label'],tag=row['tag'],field='literature_searches',old=old,new=row['literature_searches']))
for old,new in zip(oldrows,rows):
    assert {k:v for k,v in old.items() if k!='literature_searches'}=={k:v for k,v in new.items() if k!='literature_searches'}
    if old['paper']!='II' or old['label'] not in {'series:II:B','series:II:D','series:II:E'}:
        assert old==new
buffer=io.StringIO(newline=''); writer=csv.DictWriter(buffer,fieldnames=fields,lineterminator='\n')
writer.writeheader(); writer.writerows(rows); after=buffer.getvalue().encode()
receipt=R/'records/S6_SERIES_PUBLISH_II_literature_search_inventory_append_02.json'
assert not receipt.exists()
p.write_bytes(after)
receipt.write_text(json.dumps(dict(created_utc=dt.datetime.now(dt.timezone.utc).isoformat(),evidence=evidence,before_sha256=hashlib.sha256(before).hexdigest(),after_sha256=hashlib.sha256(after).hexdigest(),changes=changes,other_rows_unchanged=True,events_added=0,provenance_claims_closed=0),indent=2)+'\n')
print(json.dumps(dict(record=evidence,inventory_receipt=str(receipt.relative_to(R)),searches_recorded=len(changes),events_added=0),indent=2))
